rules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // REGLAS PARA SOPORTE TÉCNICO
    match /support_messages/{messageId} {
      // Usuario autenticado solo puede crear mensajes con su propio userId
      allow create: if request.auth != null
        && request.resource.data.userId == request.auth.uid
        && request.resource.data.keys().hasAll([
          'userId', 'category', 'message', 'channel', 'status', 'timestamp', 'deviceInfo'
        ]);

      // Usuario solo puede leer sus propios mensajes
      allow read: if request.auth != null
        && resource.data.userId == request.auth.uid;

      // Usuario solo puede actualizar sus propios mensajes (para cambiar status)
      allow update: if request.auth != null
        && resource.data.userId == request.auth.uid
        && request.resource.data.diff(resource.data).affectedKeys().hasOnly(['status', 'updatedAt']);

      // Usuario NO puede eliminar mensajes
      allow delete: if false;
    }

    match /{document=**} {
      allow read, write: if request.time < timestamp.date(2026, 12, 1);
    }
  }
}
